public static final function bool HasRequiredDLC(const out array<int> ModuleIDs)
{
    local int idx;
    local bool bAllDLCFound;

    bAllDLCFound = TRUE;
    for (idx = 0; idx < ModuleIDs.Length; ++idx)
    {
        if (!HasDLC(ModuleIDs[idx]))
        {
            bAllDLCFound = FALSE;
            break;
        }
    }
    return bAllDLCFound;
}

